WITH department_stats AS (SELECT dept_id, SUM(CASE WHEN level = 'L3' THEN 1 ELSE 0 END) AS l3_count, ROUND(STDDEV(salary), 2) AS stddev_salary FROM employees WHERE level IN ('L1', 'L2', 'L4') GROUP BY dept_id) SELECT d.id, d.budget, ds.l3_count, ds.stddev_salary FROM departments d INNER JOIN department_stats ds ON d.id = ds.dept_id WHERE ds.stddev_salary > 54 ORDER BY ds.l3_count DESC
